package com.bank.average;

import java.math.*;
import java.util.*;
import java.util.logging.*;

public class AverageDemo {
    private static final Logger log = Logger.getLogger("Average");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> employees = List.of(
            new Employee("Rajesh", "Trading", new BigDecimal("1200000")),
            new Employee("Sneha", "Trading", new BigDecimal("1500000")),
            new Employee("Rohit", "Trading", new BigDecimal("1800000")),
            new Employee("Priya", "Risk", new BigDecimal("900000")));
        AverageService service = new AverageService();

        log.info(() -> "Quick (double) avg: " + service.quickAverageByDept(employees));
        log.info(() -> "Exact (BigDecimal) avg: " + service.exactAverageByDept(employees));
    }
}

