class Employee {
    private final String name;
    private final String department;
    private final BigDecimal salary;
    Employee(String name, String department, BigDecimal salary) {
            this.name = name;
            this.department = department
            this.salary = salary;
    }
    String getDepartment() { return department; }
    BigDecimal getSalary() { return salary; }
}

// ─── Would be in service/AverageService.java ───
class AverageService {
    // fast, display-only average as double — fine for dashboards, NOT the ledger
    Map<String, Double> quickAverageByDept(List<Employee> employees) {
        return employees.stream().collect(
            java.util.stream.Collectors.groupingBy(
                Employee::getDepartment,
                java.util.stream.Collectors.averagingDouble(e -> e.getSalary().doubleValue())));
    }

    // exact average: sum BigDecimal, divide by count with scale + HALF_EVEN
    Map<String, BigDecimal> exactAverageByDept(List<Employee> employees) {
        Map<String, List<Employee>> byDept = employees.stream().collect(
            java.util.stream.Collectors.groupingBy(Employee::getDepartment));
        Map<String, BigDecimal> result = new java.util.LinkedHashMap<>();
        byDept.forEach((dept, list) -> {
            BigDecimal sum = list.stream().map(Employee::getSalary)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
            BigDecimal avg = sum.divide(
                BigDecimal.valueOf(list.size()), 2, RoundingMode.HALF_EVEN);
            result.put(dept, avg);
        });
        return result;
    }
}
